def rename_series(apps, schema_editor):
    """The "Production order" series (PRD, never used) becomes the
    "Manufacturing order" series (MO)."""
    NumberFormat = apps.get_model("core", "NumberFormat")
    for fmt in NumberFormat.objects.filter(doc_type="production_order"):
        fmt.doc_type = "manufacturing_order"
        if not fmt.counters.filter(last__gt=0).exists():
            fmt.prefix = fmt.prefix.replace("/PRD/", "/MO/").replace("PRD/", "MO/", 1)
        fmt.save(update_fields=["doc_type", "prefix"])


